{
 "app_name": "file_system",
 "api_name": "show_directory",
 "path": "/directory",
 "method": "GET",
 "description": "Show a list of files and/or sub-directories, optionally recursively, in a directory.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from file_system app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "directory_path",
   "type": "string",
   "required": false,
   "description": "Path of the directory. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": "/",
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "substring",
   "type": "string",
   "required": false,
   "description": "If passed, only files and sub-directories containing the given substring (ignoring case) will be shown.",
   "default": null,
   "constraints": []
  },
  {
   "name": "entry_type",
   "type": "string",
   "required": false,
   "description": "Whether to show all files and sub-directories, only files, or only sub-directories.",
   "default": "all",
   "constraints": [
    "value in ['all', 'files', 'directories']"
   ]
  },
  {
   "name": "recursive",
   "type": "boolean",
   "required": false,
   "description": "Whether to show files recursively.",
   "default": true,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   "string"
  ],
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "file_system",
 "api_name": "login",
 "path": "/auth/token",
 "method": "POST",
 "description": "Login to your account.",
 "parameters": [
  {
   "name": "username",
   "type": "string",
   "required": true,
   "description": "Your account email.",
   "default": null,
   "constraints": []
  },
  {
   "name": "password",
   "type": "string",
   "required": true,
   "description": "Your account password.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "access_token": "string",
   "token_type": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "file_system",
 "api_name": "move_file",
 "path": "/file/move",
 "method": "POST",
 "description": "Move a file to another location.",
 "parameters": [
  {
   "name": "source_file_path",
   "type": "string",
   "required": true,
   "description": "Path of the source file. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": null,
   "constraints": []
  },
  {
   "name": "destination_file_path",
   "type": "string",
   "required": true,
   "description": "Path of the destination file. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from file_system app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "overwrite",
   "type": "boolean",
   "required": false,
   "description": "Whether to overwrite the file if it already exists.",
   "default": false,
   "constraints": []
  },
  {
   "name": "retain_dates",
   "type": "boolean",
   "required": false,
   "description": "Whether the moved file should retain the original file's created and updated dates.",
   "default": false,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "destination_file_path": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

